<template>
 <view class="wish-wall">
  <view class="wish-sky" :class="{still:!motion}">
   <view class="board-pin pin-left"></view><view class="board-pin pin-right"></view>
   <view class="sky-heading"><text class="eyebrow">A LITTLE WISH, A LITTLE CLOSER</text><text class="sky-title">小时心愿板</text><text class="sky-caption">把期待留在这里，和大家一起慢慢实现。</text></view>
   <view class="meteor-field" aria-label="流星愿望展示">
    <view v-for="(wish,index) in meteors" :key="wish.id" class="meteor" :style="{top:(index%6*70+20)+'rpx',animationDelay:(-8-index*3.3)+'s',animationDuration:'28s'}" @click="detail(wish)"><text class="meteor-star">✦</text><text class="meteor-text">{{wish.fulfilled?'已实现 · ':''}}{{wish.content}}</text><text class="meteor-tail"></text></view>
    <view v-if="!wishes.length" class="sky-empty"><CartoonArt class="empty-mail" kind="letter" label="等待心愿的星星信封"/><text>这里还没有心愿纸条。</text><text>写下第一份期待，小时会替你好好收藏。</text></view>
   </view>
   <view class="sky-footer"><text>{{wishes.length?'最近 '+wishes.length+' 个心愿':'每一个认真许下的愿望，都值得被看见'}}</text><button class="motion-button" @click="motion=!motion">{{motion?'暂停流星':'开启流星'}}</button></view>
  </view>
  <view class="card wish-compose"><text class="eyebrow">MAKE A LITTLE WISH</text><text class="title">写给未来的自己</text><textarea v-model="content" maxlength="100" placeholder="希望这一次，我可以成为更勇敢的自己……"/><view class="row between space"><text class="section-meta">{{content.length}} / 100</text><view class="row"><text class="muted">匿名发布</text><switch :checked="anonymous" color="#ab9067" @change="anonymous=$event.detail.value"/></view></view>
   <view class="consent row" @click="ack=!ack"><text class="consent-box">{{ack?'☑':'☐'}}</text><text>我知道愿望会对所有登录用户公开；不填写联系方式或其他隐私。</text></view>
   <button class="primary" :disabled="busy||!ack" @click="publish">让愿望化作流星 ✦</button><text v-if="error" class="error space">{{error}}</text><text class="footnote">每人每天最多 5 条，两次发布间隔 30 秒。可随时删除自己的愿望。</text>
  </view>
  <view class="card"><view class="row between"><text class="title">落在这里的心愿</text><button class="secondary small" :disabled="loading" @click="load">刷新愿望</button></view><view class="segment"><button :class="{selected:!onlyMine}" @click="onlyMine=false">大家的愿望</button><button :class="{selected:onlyMine}" @click="onlyMine=true">我的愿望</button></view>
   <view v-for="wish in displayed" :key="wish.id" class="wish-entry"><view class="row between"><text class="wish-author">✧ {{wish.author}}</text><text class="section-meta">{{wish.fulfilled?'愿望已实现 ✦':dateLabel(wish.created_at)}}</text></view><text class="wish-content">{{wish.content}}</text><view class="wish-actions"><template v-if="wish.mine"><button class="secondary small" :disabled="busy" @click="fulfill(wish)">{{wish.fulfilled?'重新许愿':'我来还愿'}}</button><button class="danger small" :disabled="busy" @click="remove(wish)">删除愿望</button></template><button v-else class="secondary small" :disabled="busy" @click="report(wish)">举报并隐藏</button></view></view>
   <text v-if="!displayed.length" class="muted">{{onlyMine?'你还没有留下愿望。':'暂时没有愿望，来做第一颗星吧。'}}</text>
  </view>
 </view>
</template>
<script setup>
import CartoonArt from './CartoonArt.vue';
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {store} from '../services/store';import {request,confirm,inform,message,token} from '../services/api';
const props=defineProps({active:Boolean});const wishes=ref([]),mine=ref([]),content=ref(''),anonymous=ref(true),ack=ref(false),motion=ref(false),onlyMine=ref(false),busy=ref(false),loading=ref(false),error=ref(''),batch=ref(0);let timer,meteorTimer,epoch=0;
const meteors=computed(()=>{const start=(batch.value%Math.max(1,Math.ceil(wishes.value.length/6)))*6;return wishes.value.slice(start,start+6);});const displayed=computed(()=>onlyMine.value?mine.value:wishes.value);
async function load(){if(!props.active||!store.user)return;const ticket=++epoch,auth=token();loading.value=true;try{const data=await request('/wishes');if(ticket!==epoch||auth!==token())return;wishes.value=data.wishes;mine.value=data.mine;error.value='';}catch(e){if(ticket===epoch)error.value=e.message;}finally{if(ticket===epoch)loading.value=false;}}
watch(()=>[props.active,store.user?.id],([active,id],[,previousId]=[])=>{clearInterval(timer);clearInterval(meteorTimer);epoch++;loading.value=false;batch.value=0;if(id!==previousId){wishes.value=[];mine.value=[];content.value='';ack.value=false;error.value='';}if(active&&id){load();timer=setInterval(load,20000);meteorTimer=setInterval(()=>{if(motion.value)batch.value++;},28000);}},{immediate:true});onBeforeUnmount(()=>{clearInterval(timer);clearInterval(meteorTimer);epoch++;});
async function mutate(path,method,data){if(busy.value)return false;busy.value=true;error.value='';try{await request(path,method,data);await load();return true;}catch(e){error.value=e.message;return false;}finally{busy.value=false;}}
async function publish(){if(!ack.value)return;if(await mutate('/wishes','POST',{content:content.value,anonymous:anonymous.value,public_ack:ack.value})){batch.value=0;content.value='';ack.value=false;message('愿望已飞向星空');}}
async function fulfill(wish){await mutate('/wishes/'+wish.id,'PATCH',{fulfilled:!wish.fulfilled});}
async function remove(wish){if(await confirm('删除这条公开愿望？其他人刷新后将不再看到。'))await mutate('/wishes/'+wish.id,'DELETE');}
async function report(wish){if(await confirm('举报并隐藏这条愿望？'))await mutate('/wishes/'+wish.id+'/report','POST',{});}
function detail(wish){inform(wish.content,wish.author+(wish.fulfilled?' · 已还愿':''));}
function dateLabel(value){return new Date(Date.parse(value)+8*3600000).toISOString().slice(0,10);}
</script>
