tom:-100rpx;left:-10%;width:100%;height:230rpx;background:#5a4934;border-radius:50% 70% 0 0;transform:rotate(-10deg)}.hill-two{left:40%;bottom:-140rpx;background:#3f382e;transform:rotate(12deg)}.sky-footer{position:absolute;left:30rpx;right:30rpx;bottom:27rpx;display:flex;align-items:center;justify-content:space-between;font-size:19rpx;color:#e9dcc1}.motion-button{font-size:20rpx;background:#ffffff14;color:#f7f0e2;padding:14rpx 18rpx;border:1rpx solid #ffffff22}.wish-compose textarea{height:190rpx;min-height:190rpx}.consent{margin:26rpx 0;color:#8d734f;font-size:22rpx;line-height:1.8;align-items:flex-start}.consent-box{font-size:34rpx;line-height:1.2}.wish-entry{padding:30rpx 0;border-bottom:2rpx solid #f7f0e2}.wish-author{font-size:23rpx;color:#ab9067}.wish-content{display:block;margin:18rpx 0;font-size:28rpx;line-height:1.9;color:#5a4934;overflow-wrap:anywhere;white-space:pre-wrap}.wish-actions{display:flex;gap:16rpx;justify-content:flex-end}@keyframes fly{from{transform:translateX(0) translateY(-12rpx);opacity:0}8%{opacity:1}90%{opacity:1}to{transform:translateX(-240%) translateY(22rpx);opacity:0}}@media(prefers-reduced-motion:reduce){.meteor{animation:none;left:7%}}
