.wish-sky{height:700rpx;background:#f8edcf;border:8rpx solid #dfc596;border-radius:20rpx;box-shadow:0 8rpx 0 #efe2c2}.sky-heading{padding:38rpx 28rpx 16rpx}.sky-heading .eyebrow{font-size:17rpx;letter-spacing:1rpx}.sky-title{font-size:36rpx;letter-spacing:0;margin:8rpx 0 12rpx}.sky-caption{font-size:24rpx}.meteor-field{top:175rpx;height:440rpx}.board-pin{position:absolute;top:12rpx;width:12rpx;height:12rpx;border-radius:50%;background:#ba8e4b;box-shadow:0 3rpx 0 #8f6b36}.pin-left{left:18rpx}.pin-right{right:18rpx}.still .meteor{left:5%;width:90%;height:58rpx;gap:12rpx}.meteor-text{max-width:90%;background:#fffdf5;border:0;border-bottom:3rpx solid #e2cf9f;border-radius:5rpx 14rpx 14rpx 5rpx;padding:12rpx 22rpx;font-size:24rpx}.still .meteor-tail{display:none}.sky-empty{padding:42rpx 20rpx;color:#8e744b}.empty-mail{width:110rpx;height:110rpx}.sky-footer{font-size:21rpx;bottom:20rpx}.motion-button{min-height:65rpx;padding:14rpx 18rpx}
